{"code":"import pandas as pd
import numpy as np

def score_phq9(raw_df):
    items = [f'phq9_{i}' for i in range(1, 10)]
    totals = []
    bands = []
    prorated = []
    self_harm = []

    for idx, row in raw_df.iterrows():
        ans = []
        for it in items:
            val = row[it]
            if pd.isna(val) or val == -9 or val < 0 or val > 3:
                ans.append(np.nan)
            else:
                ans.append(int(val))

        # Self-harm flag
        q9 = ans[8]
        if pd.isna(q9):
            self_harm.append(np.nan)
        else:
            self_harm.append(True if q9 >= 1 else False)

        n_missing = sum(pd.isna(ans))
        if n_missing >= 2:
            totals.append(np.nan)
            bands.append(np.nan)
            prorated.append(np.nan)
        elif n_missing == 1:
            s = sum([x for x in ans if not pd.isna(x)])
            # scale up: s * 9 / 8, round half up
            from decimal import Decimal, ROUND_HALF_UP
            val_scaled = Decimal(s) * Decimal(9) / Decimal(8)
            tot = int(val_scaled.quantize(Decimal('1'), rounding=ROUND_HALF_UP))
            totals.append(tot)
            prorated.append(True)
            bands.append(get_phq9_band(tot))
        else:
            tot = sum(ans)
            totals.append(tot)
            prorated.append(False)
            bands.append(get_phq9_band(tot))

    return pd.DataFrame({
        'respondent_id': raw_df['respondent_id'],
        'phq9_total': totals,
        'phq9_band': bands,
        'phq9_prorated': prorated,
        'phq9_self_harm_flag': self_harm
    })

def get_phq9_band(tot):
    if pd.isna(tot):
        return np.nan
    if tot <= 4:
        return "none-minimal"
    elif tot <= 9:
        return "mild"
    elif tot <= 14:
        return "moderate"
    elif tot <= 19:
        return "moderately severe"
    else:
        return "severe"

