        ans = []
        for i, it in enumerate(items, 1):
            val = row[it]
            if pd.isna(val) or val == -9 or val < 0 or val > 3:
                ans.append(np.nan)
            else:
                v = int(val)
                if i in rev_items:
                    v = 3 - v
                ans.append(v)

        n_missing = sum(pd.isna(ans))
        if n_missing >= 2:
            totals.append(np.nan)
            prorated.append(np.nan)
        elif n_missing == 1:
            s = sum([x for x in ans if not pd.isna(x)])
            from decimal import Decimal, ROUND_HALF_UP
            val_scaled = Decimal(s) * Decimal(10) / Decimal(9)
            tot = int(val_scaled.quantize(Decimal('1'), rounding=ROUND_HALF_UP))
            totals.append(tot)
            prorated.append(True)
        else:
            tot = sum(ans)
            totals.append(tot)
            prorated.append(False)

    return pd.DataFrame({
        'respondent_id': raw_df['respondent_id'],
        'rses_total': totals,
        'rses_prorated': prorated
    })

raw = pd.read_csv('raw_responses.csv')
pipeline = pd.read_csv('pipeline_output.csv')

p_phq = score_phq9(raw)
p_gad = score_gad7(raw)
p_rses = score_rses(raw)

my_out = p_phq.merge(p_gad, on='respondent_id').merge(p_rses, on='respondent_id')

# Compare column by column
print("Comparison with pipeline:")
for col in pipeline.columns:
    if col == 'respondent_id':
        continue
    s_pipe = pipeline[col]
    s_my = my_out[col]

    # handle bool / nan / object comparison
    eq = s_pipe.eq(s_my) | (s_pipe.isna() & s_my.isna())
    diffs = (~eq).sum()
    print(f"{col}: {diffs} differences")
    if diffs > 0:
        mismatch = raw[~eq]
        print(f"  First few mismatch IDs: {mismatch['respondent_id'].head(3).tolist()}")
